insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_stats_v1'
from (values
('111.47.c.2.A',3,'In a simple random sample, how is each member of the population treated?','["each member has an equal chance of being chosen", "only convenient members are chosen", "the first members listed are chosen", "volunteers are chosen"]'::jsonb,0,'Random selection reduces bias.','original'),
('111.47.c.2.A',3,'A researcher surveys only the people who walk past her office. What type of sample is this?','["a census", "a convenience sample", "a simple random sample", "a stratified sample"]'::jsonb,1,'It uses whoever is easy to reach.','original'),
('111.47.c.2.A',4,'A school splits students by grade level and then randomly selects some from each grade. What is this called?','["convenience sampling", "voluntary response sampling", "stratified random sampling", "cluster sampling"]'::jsonb,2,'Groups (strata) are each sampled.','original'),
('111.47.c.2.A',3,'Why is a voluntary response sample often biased?','["everyone is chosen at random", "it samples the whole population", "it removes all variability", "people with strong opinions are more likely to respond"]'::jsonb,3,'Self-selected responders are not representative.','original'),
('111.47.c.2.B',3,'Which kind of study assigns treatments to subjects?','["an experiment", "an observational study", "a survey", "a census"]'::jsonb,0,'Researchers impose the treatment.','original'),
('111.47.c.2.B',3,'A researcher records the habits of students without changing anything. What is this?','["an experiment", "an observational study", "a simulation", "a placebo trial"]'::jsonb,1,'No treatment is imposed.','original'),
('111.47.c.2.B',3,'A poll asks 1,000 voters about a candidate. What type of study is this?','["an observational study of a treatment", "a double-blind trial", "a survey", "an experiment"]'::jsonb,2,'It gathers responses to questions.','original'),
('111.47.c.2.C',4,'A well-designed experiment with random assignment can support which kind of conclusion?','["only a correlation", "no conclusion", "a conclusion about the whole world", "a cause-and-effect conclusion"]'::jsonb,3,'Random assignment controls for confounding.','original'),
('111.47.c.2.C',4,'An observational study finds that ice cream sales and sunburns rise together. What is the best conclusion?','["no cause is shown; a lurking variable such as hot weather may explain both", "the data must be wrong", "sunburns cause ice cream sales", "ice cream causes sunburns"]'::jsonb,0,'Association does not prove causation.','original'),
('111.47.c.2.C',4,'Results from a sample can be generalized to a population only if the sample was what?','["chosen by the researcher", "randomly selected and representative", "chosen by volunteers", "very small"]'::jsonb,1,'Random selection supports generalization.','original'),
('111.47.c.2.D',2,'A number that describes a sample is called what?','["a population", "a census", "a statistic", "a parameter"]'::jsonb,2,'Statistics describe samples.','original'),
('111.47.c.2.D',2,'A number that describes an entire population is called what?','["a sample", "a statistic", "a variable only", "a parameter"]'::jsonb,3,'Parameters describe populations.','original'),
('111.47.c.2.D',3,'In a poll, 52% of 400 sampled voters support a measure. What is the 52%?','["a sample statistic", "a z-score", "a margin of error", "a population parameter"]'::jsonb,0,'It comes from the sample.','original'),
('111.47.c.2.E',3,'What is the first step in a statistical investigation?','["choose a conclusion", "ask a question that can be answered with data", "draw a graph", "calculate the mean"]'::jsonb,1,'Start by formulating a question.','original'),
('111.47.c.2.E',3,'Which question can be answered using data?','["Is math the best subject?", "Is blue the prettiest color?", "How many hours do students at our school sleep on weeknights?", "Should everyone like pizza?"]'::jsonb,2,'It asks about measurable values.','original'),
('111.47.c.2.E',3,'After collecting data, what comes before drawing conclusions?','["asking the question again", "writing a title", "choosing a sample", "analyzing the data"]'::jsonb,3,'The data must be summarized and examined.','original'),
('111.47.c.2.F',3,'When reporting a study, which detail should be included so others can judge it?','["how the sample was selected", "the researcher''s favorite color", "the day of the week it was written", "nothing about methods"]'::jsonb,0,'Methods affect the reliability of results.','original'),
('111.47.c.2.F',3,'A good conclusion in a data project should be tied to what?','["guesses about other data", "the data and analysis that were collected", "opinion only", "the research question only"]'::jsonb,1,'Claims must be supported by evidence.','original'),
('111.47.c.2.F',3,'Which graph is best for showing the shape of the distribution of one quantitative variable?','["a scatterplot of two variables", "a bar chart of names", "a histogram", "a pie chart for categories"]'::jsonb,2,'A histogram shows the spread and shape.','original'),
('111.47.c.2.G',4,'A news report says ''Coffee drinkers live longer'' based on an observational study. What is a key concern?','["correlation always shows causation", "the study is an experiment", "the sample is too random", "confounding variables may explain the result"]'::jsonb,3,'Other factors may be involved.','original'),
('111.47.c.2.G',4,'A survey about school lunches only asks students who buy lunch. What is the problem?','["undercoverage: students who bring lunch are missing", "the question was too long", "too many students were sampled", "the sample was random"]'::jsonb,0,'Part of the population is left out.','original'),
('111.47.c.2.G',4,'A poll asks ''Don''t you agree that the wonderful new park should be built?'' What is the problem?','["the poll is unbiased", "the wording is leading and biases the responses", "it is not a survey", "the sample is too large"]'::jsonb,1,'Question wording can push answers.','original'),
('111.47.c.3.A',3,'Which describes a mathematical (deterministic) model?','["it uses sample data only", "outputs vary randomly around a pattern", "the same inputs always give the same output", "it cannot be graphed"]'::jsonb,2,'There is no random variation.','original'),
('111.47.c.3.A',3,'Which describes a statistical model?','["it gives exact outputs with no variation", "it ignores data", "it only works for one point", "it describes a pattern and also the random variation around it"]'::jsonb,3,'Real data vary.','original'),
('111.47.c.3.A',3,'The equation d = 50t gives the distance driven at 50 mph. What kind of model is it?','["a mathematical model", "a statistical model", "a survey", "a sampling model"]'::jsonb,0,'It ignores traffic and other variation.','original'),
('111.47.c.3.B',4,'A line of best fit predicts a plant''s height from sunlight hours, but real plants scatter around it. What does the scatter represent?','["a population parameter", "variability around the model", "a mistake in the line", "a perfect fit"]'::jsonb,1,'Residuals show the variation not explained.','original'),
('111.47.c.3.B',4,'In a statistical model y = a + bx + error, what does the error term represent?','["the intercept", "the slope", "random variation not explained by x", "the sample size"]'::jsonb,2,'It is the unexplained part.','original'),
('111.47.c.3.B',3,'Why might a statistical model be better than a mathematical model for predicting test scores from study time?','["study time has no effect", "scores never vary", "math cannot be used", "scores vary even when study time is the same"]'::jsonb,3,'Individual differences create variation.','original'),
('111.47.c.3.C',3,'Different students having different heights is an example of what kind of variability?','["natural variability", "measurement variability", "induced variability", "sampling variability"]'::jsonb,0,'It occurs in nature.','original'),
('111.47.c.3.C',3,'Slightly different readings from a scale when weighing the same object are an example of what?','["induced variability", "measurement variability", "natural variability", "sampling variability"]'::jsonb,1,'The measuring process is imperfect.','original'),
('111.47.c.3.C',4,'Different random samples from the same population give slightly different means. What is this called?','["measurement variability", "natural variability only", "sampling variability", "induced variability"]'::jsonb,2,'Each sample differs by chance.','original'),
('111.47.c.3.C',3,'A researcher changes the fertilizer given to plants and sees growth change. What kind of variability is this?','["natural variability", "measurement variability", "sampling variability", "induced variability"]'::jsonb,3,'The researcher caused the change.','original'),
('111.47.c.3.D',3,'What is a sampling distribution?','["the distribution of a statistic over many samples", "a graph of one individual", "a list of all populations", "the distribution of one sample only"]'::jsonb,0,'It shows how a statistic varies across samples.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_stats_v1'
from (values
('111.47.c.3.D',4,'As the sample size increases, what happens to the spread of the sampling distribution of the mean?','["it becomes uniform", "it decreases", "it increases", "it stays the same"]'::jsonb,1,'The standard error is σ ÷ √n.','original'),
('111.47.c.3.D',4,'The standard deviation of a population is 20. What is the standard error of the mean for samples of size 100?','["0.2", "200", "2", "20"]'::jsonb,2,'20 ÷ √100.','original'),
('111.47.c.4.A',2,'Which variable is categorical?','["weight in pounds", "height in inches", "age in years", "eye color"]'::jsonb,3,'It places individuals into groups.','original'),
('111.47.c.4.A',2,'Which variable is quantitative?','["number of siblings", "favorite color", "type of pet", "zip code label as a category"]'::jsonb,0,'It is a count with numerical meaning.','original'),
('111.47.c.4.A',3,'A survey asks for a student''s grade level (9, 10, 11 or 12). How can this variable be treated?','["as a z-score", "as categorical, since averages of labels are not meaningful here", "as a proportion", "as a continuous measurement only"]'::jsonb,1,'The numbers act as labels for groups.','original'),
('111.47.c.4.B',3,'Which graph is best for comparing the percentage of students choosing each of four lunch options?','["a histogram of heights", "a scatterplot", "a bar graph", "a boxplot of one variable"]'::jsonb,2,'Bar graphs display categorical data.','original'),
('111.47.c.4.B',3,'Which graph shows the five-number summary of a data set?','["a scatterplot", "a bar graph", "a pie chart", "a boxplot"]'::jsonb,3,'It shows min, Q1, median, Q3 and max.','original'),
('111.47.c.4.B',3,'A dot plot is best used for what?','["small sets of quantitative data", "two-variable relationships", "time only", "very large sets of categories"]'::jsonb,0,'Each dot is one data value.','original'),
('111.47.c.4.C',3,'A distribution has a long tail to the right. What is its shape?','["symmetric", "skewed right", "skewed left", "uniform"]'::jsonb,1,'The tail points toward higher values.','original'),
('111.47.c.4.C',3,'In a right-skewed distribution, how does the mean compare with the median?','["they are equal", "the mean is less than the median", "the mean is greater than the median", "the mean cannot be found"]'::jsonb,2,'The tail pulls the mean up.','original'),
('111.47.c.4.C',4,'A data value is flagged as an outlier if it is more than how many IQRs beyond the quartiles?','["5", "0.5", "3", "1.5"]'::jsonb,3,'The 1.5 × IQR rule.','original'),
('111.47.c.4.C',3,'Which statistic is resistant to outliers?','["the median", "the mean", "the range", "the standard deviation"]'::jsonb,0,'Extreme values barely change it.','original'),
('111.47.c.4.D',3,'Which graph best shows the individual values in a small data set?','["a pie chart", "a dot plot", "a bar graph of counts", "a box plot"]'::jsonb,1,'Each value is visible.','original'),
('111.47.c.4.D',4,'A boxplot and a histogram are made from the same data. Which shows the shape in more detail?','["neither", "the boxplot", "the histogram", "both show exactly the same"]'::jsonb,2,'Boxplots hide gaps and peaks.','original'),
('111.47.c.4.D',3,'What does a boxplot show well that a bar graph of means does not?','["the cause of variation", "the sample size only", "the exact population", "the spread of the data"]'::jsonb,3,'Quartiles show variability.','original'),
('111.47.c.4.E',3,'Two data sets have the same mean but different standard deviations. What does that tell us?','["the set with the larger standard deviation is more spread out", "the sets are identical", "the medians must differ", "the set with the larger standard deviation is more centered"]'::jsonb,0,'Standard deviation measures spread.','original'),
('111.47.c.4.E',3,'What is the mean of 2, 4, 6, 8?','["4", "5", "6", "20"]'::jsonb,1,'20 ÷ 4.','original'),
('111.47.c.4.E',3,'What is the median of 3, 5, 7, 9, 11, 13?','["9", "7", "8", "6"]'::jsonb,2,'The average of the middle values, 7 and 9.','original'),
('111.47.c.4.E',4,'For the data 10, 12, 14, 16, 18, what is the range?','["14", "4", "18", "8"]'::jsonb,3,'18 − 10.','original'),
('111.47.c.4.F',3,'In a two-way table, what is a marginal distribution?','["the totals for one variable alone", "the mean of the table", "the standard deviation", "the intersection of both variables"]'::jsonb,0,'It is found in the margins.','original'),
('111.47.c.4.F',4,'In a two-way table, 20 of 80 students who play sports are seniors. What is the conditional relative frequency of seniors among athletes?','["4%", "25%", "75%", "20%"]'::jsonb,1,'20 ÷ 80.','original'),
('111.47.c.4.F',3,'What does a two-way table display?','["the slope of a line", "the shape of one quantitative variable", "the relationship between two categorical variables", "the mean of two groups"]'::jsonb,2,'Categories are cross-classified.','original'),
('111.47.c.5.A',2,'A fair six-sided die is rolled. What is P(rolling an even number)?','["1/3", "1/6", "2/3", "1/2"]'::jsonb,3,'3 of 6 outcomes.','original'),
('111.47.c.5.A',3,'A bag has 3 red and 7 blue marbles. What is the probability of drawing a red marble?','["3/10", "7/10", "3/7", "1/3"]'::jsonb,0,'3 of 10 marbles are red.','original'),
('111.47.c.5.A',3,'P(A) = 0.4 and P(B) = 0.3, and A and B are independent. What is P(A and B)?','["0.1", "0.12", "0.35", "0.7"]'::jsonb,1,'Multiply for independent events.','original'),
('111.47.c.5.A',4,'P(A) = 0.5, P(B) = 0.4 and P(A and B) = 0.2. What is P(A or B)?','["0.45", "0.2", "0.7", "0.9"]'::jsonb,2,'0.5 + 0.4 − 0.2.','original'),
('111.47.c.5.B',3,'According to the Law of Large Numbers, as the number of trials increases, what happens to the experimental probability?','["it always equals 1/2", "it moves away from the theoretical probability", "it stops changing at the start", "it gets closer to the theoretical probability"]'::jsonb,3,'Long-run relative frequency approaches the true value.','original'),
('111.47.c.5.B',3,'A coin lands heads 6 times in 10 flips and 5,010 times in 10,000 flips. Which is closer to the theoretical value?','["the 10,000 flips", "the 10 flips", "they are equally close", "neither is related"]'::jsonb,0,'More trials give a better estimate.','original'),
('111.47.c.5.B',3,'A fair coin has landed heads five times in a row. What is the probability of heads on the next flip?','["0", "1/2", "less than 1/2", "more than 1/2"]'::jsonb,1,'Flips are independent.','original'),
('111.47.c.5.C',4,'A simulation tosses a coin 10 times and counts heads, repeated many times. What does the distribution of the counts represent?','["a single trial", "the population mean", "the distribution of the number of heads", "a census"]'::jsonb,2,'Each repeat yields one count.','original'),
('111.47.c.5.C',3,'Why is simulation useful in statistics?','["it removes randomness", "it replaces all data", "it gives exact answers every time", "it estimates probabilities that are hard to calculate exactly"]'::jsonb,3,'Repeated trials approximate the true distribution.','original'),
('111.47.c.5.C',3,'If 38 out of 100 simulated trials produce a success, what is the estimated probability?','["0.38", "38", "0.62", "3.8"]'::jsonb,0,'Relative frequency.','original'),
('111.47.c.5.D',4,'A simulation of 1,000 samples gives a sample mean of 49.8 while the population mean is 50. What does this suggest?','["the simulation is wrong", "the simulation is close to the true value", "the population mean is 49.8", "the standard deviation is zero"]'::jsonb,1,'Small differences are expected.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_stats_v1'
from (values
('111.47.c.5.D',4,'When comparing a simulated standard deviation to a theoretical one, what do you expect with more repetitions?','["a different mean", "greater disagreement", "closer agreement", "no change"]'::jsonb,2,'More repetitions reduce simulation error.','original'),
('111.47.c.5.D',3,'A theoretical mean of a distribution is 10. A simulation gives 10.2. What explains the difference?','["the mean is undefined", "the theory is wrong", "the simulation is impossible", "random variation in the simulation"]'::jsonb,3,'Simulated results vary by chance.','original'),
('111.47.c.6.A',3,'A confidence interval is built from a sample statistic and what?','["a margin of error", "a random digit", "the sample''s median only", "a population parameter"]'::jsonb,0,'Interval = statistic ± margin of error.','original'),
('111.47.c.6.A',3,'What does a 95% confidence level mean?','["there is a 95% chance the sample is correct", "about 95% of intervals constructed this way capture the true parameter", "the parameter changes 95% of the time", "95% of the data are in the interval"]'::jsonb,1,'It describes the long-run success rate.','original'),
('111.47.c.6.A',3,'A sample mean is 50 with a margin of error of 4. What is the confidence interval?','["(50, 54)", "(48, 52)", "(46, 54)", "(44, 56)"]'::jsonb,2,'50 − 4 to 50 + 4.','original'),
('111.47.c.6.B',3,'If the sample size increases and other things stay the same, what happens to the margin of error?','["it stays the same", "it becomes zero", "it increases", "it decreases"]'::jsonb,3,'More data give more precision.','original'),
('111.47.c.6.B',3,'If the confidence level increases from 90% to 99%, what happens to the margin of error?','["it increases", "it decreases", "it is zero", "it stays the same"]'::jsonb,0,'A wider interval is needed for more confidence.','original'),
('111.47.c.6.B',4,'If the population standard deviation increases, what happens to the margin of error?','["it stays the same", "it increases", "it becomes negative", "it decreases"]'::jsonb,1,'More variability means less precision.','original'),
('111.47.c.6.C',4,'A sample of 100 has mean 80 and population σ = 10. What is the standard error of the mean?','["0.1", "100", "1", "10"]'::jsonb,2,'σ ÷ √n.','original'),
('111.47.c.6.C',4,'Using z* = 2 for roughly 95% confidence, a sample mean is 80 with standard error 1. What is the interval?','["(80, 82)", "(79, 81)", "(70, 90)", "(78, 82)"]'::jsonb,3,'80 ± 2(1).','original'),
('111.47.c.6.C',4,'Which z* value is closest to 95% confidence for a normal distribution?','["1.96", "0.95", "2.58", "1.28"]'::jsonb,0,'The middle 95% lies within about 1.96 standard errors.','original'),
('111.47.c.6.D',4,'In a sample of 100 voters, 60 support a measure. What is the sample proportion?','["60", "0.60", "0.06", "0.40"]'::jsonb,1,'60 ÷ 100.','original'),
('111.47.c.6.D',4,'What is the standard error of p̂ = 0.6 when n = 100?','["about 0.5", "about 0.6", "about 0.049", "about 0.4"]'::jsonb,2,'√(0.6 × 0.4 ÷ 100).','original'),
('111.47.c.6.D',4,'Which interval is a 95% confidence interval for a proportion when p̂ = 0.60 and the margin of error is 0.096?','["(0.6, 0.696)", "(0.404, 0.796)", "(0.5, 0.7)", "(0.504, 0.696)"]'::jsonb,3,'p̂ ± margin of error.','original'),
('111.47.c.6.E',3,'A 95% confidence interval for a mean is (10, 14). Which interpretation is correct?','["we are 95% confident the true mean is between 10 and 14", "95% of the data are between 10 and 14", "the true mean is 12 with 95% probability", "the sample mean is between 10 and 14 with 95% probability"]'::jsonb,0,'It is a statement about the parameter.','original'),
('111.47.c.6.E',4,'A confidence interval for a difference in means is (−2, 5). What does this suggest?','["the means are definitely equal", "zero is a plausible difference", "the interval is invalid", "the means are definitely different"]'::jsonb,1,'The interval includes 0.','original'),
('111.47.c.6.E',4,'Two confidence intervals for a proportion, (0.40, 0.50) and (0.55, 0.65), do not overlap. What does this suggest?','["the intervals are wrong", "the proportions are the same", "the two population proportions are probably different", "the sample sizes are equal"]'::jsonb,2,'No plausible common value.','original'),
('111.47.c.6.F',3,'A coin lands heads 90 out of 100 times. What does this suggest about the claim that the coin is fair?','["it means nothing", "it proves the claim", "it supports the claim", "it provides evidence against the claim"]'::jsonb,3,'Such a result is very unlikely if p = 0.5.','original'),
('111.47.c.6.F',4,'A claim is tested using a sample statistic. Why might the statistic differ from the claimed value even if the claim is true?','["sampling variability", "the population has no mean", "measurement is impossible", "the claim is false"]'::jsonb,0,'Samples vary by chance.','original'),
('111.47.c.6.F',4,'When a sample result would be very unlikely if the claim were true, what do we conclude?','["the claim is true", "the claim is questionable", "the sample is wrong", "no conclusion is possible"]'::jsonb,1,'Unlikely outcomes are evidence against it.','original'),
('111.47.c.6.G',3,'A company claims the mean battery life is 20 hours. Which is the null hypothesis?','["H₀: μ ≠ 20", "H₀: μ > 20", "H₀: μ = 20", "H₀: x̄ = 20"]'::jsonb,2,'The null states no change.','original'),
('111.47.c.6.G',3,'You want to test whether a new teaching method raises the mean score above 70. What is the alternative hypothesis?','["Hₐ: μ < 70", "Hₐ: μ ≠ 70", "Hₐ: μ = 70", "Hₐ: μ > 70"]'::jsonb,3,'The research claim is the alternative.','original'),
('111.47.c.6.G',3,'Hypotheses are statements about what?','["population parameters", "sample statistics", "the p-value", "the sample size"]'::jsonb,0,'They concern the population, not the sample.','original'),
('111.47.c.6.H',4,'What does the p-value measure?','["the sample size", "the probability of a result at least as extreme as observed, if H₀ is true", "the probability that H₀ is true", "the probability that Hₐ is true"]'::jsonb,1,'It assumes the null is true.','original'),
('111.47.c.6.H',3,'At α = 0.05, a test gives p = 0.02. What is the decision?','["accept H₀", "fail to reject H₀", "reject H₀", "the test is invalid"]'::jsonb,2,'p is less than α.','original'),
('111.47.c.6.H',3,'At α = 0.05, a test gives p = 0.30. What is the decision?','["the p-value is wrong", "accept Hₐ", "reject H₀", "fail to reject H₀"]'::jsonb,3,'The evidence is not strong enough.','original'),
('111.47.c.6.H',4,'A smaller p-value provides what kind of evidence against H₀?','["stronger evidence", "no evidence", "evidence for H₀", "weaker evidence"]'::jsonb,0,'The result is less compatible with the null.','original'),
('111.47.c.6.I',4,'A technology output for a one-sample t test shows t = 2.5 and p = 0.015. At α = 0.05, what do we conclude?','["there is not significant evidence against H₀", "there is significant evidence against H₀", "the test cannot be used", "H₀ is proven true"]'::jsonb,1,'p < α.','original'),
('111.47.c.6.I',4,'A large sample is required for which kind of test?','["no test", "any test", "a z test for a proportion using a normal approximation", "a test of a single data point"]'::jsonb,2,'Conditions such as np and n(1 − p) being large must hold.','original'),
('111.47.c.6.I',4,'A technology output reports a 95% confidence interval for μ of (4.1, 5.9) and a test of H₀: μ = 4 gives p = 0.04. Are these consistent?','["no, they contradict", "yes, because p = 0.04 means 4 is inside the interval", "no, because the interval is too wide", "yes, 4 is just outside the interval and p < 0.05"]'::jsonb,3,'A value outside a 95% interval is rejected at α = 0.05.','original'),
('111.47.c.6.J',3,'What is a Type I error?','["rejecting a true null hypothesis", "failing to reject a true null hypothesis", "rejecting a false null hypothesis", "failing to reject a false null hypothesis"]'::jsonb,0,'A false positive.','original'),
('111.47.c.6.J',3,'What is a Type II error?','["rejecting a false null hypothesis", "failing to reject a false null hypothesis", "failing to reject a true null hypothesis", "rejecting a true null hypothesis"]'::jsonb,1,'A false negative.','original'),
('111.47.c.6.J',4,'The significance level α equals the probability of what?','["a Type II error", "a correct decision", "a Type I error", "the power of the test"]'::jsonb,2,'α is the chance of rejecting a true null.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_stats_v1'
